function openForm(kind,record={},extra={}){editing={kind,record:{...record,...extra},callback:null};fieldDefs=defs(kind,editing.record);$('#modal-title').textContent=(record.id?'Ubah ':'Tambah ')+({vehicles:'kendaraan',drivers:'pengemudi',customers:'pelanggan',routes:'rute',trips:'jadwal travel',bookings:'pemesanan',entries:'transaksi kas',expenses:'tagihan pengeluaran',accounts:'akun',loans:'pinjaman',collaterals:'jaminan',settings:'pengaturan'}[kind]||kind);$('#fields').innerHTML=fieldDefs.map(d=>fieldHtml(d,editing.record)).join('');$('#form-note').textContent=({entries:'Catat uang yang benar-benar diterima/dibayar. Pemotongan jaminan memindahkan kewajiban jaminan ke pembayaran tagihan tanpa arus kas. Transaksi tidak dapat diedit setelah disimpan.',expenses:'Ini adalah tagihan biaya. Setelah disimpan, klik Bayar untuk mencatat uang keluar. Pokok cicilan dicatat melalui transaksi Pokok cicilan, bukan biaya.',bookings:'Konfirmasi memeriksa benturan jadwal dan kapasitas. Rental lepas kunci memerlukan SIM yang masih berlaku. Serah terima memerlukan verifikasi dokumen dan jaminan yang sudah diterima.',collaterals:'Jaminan kendaraan bukan aset atau kas usaha. Catat pemeriksaan kondisi dan bukti serah terima di kedua tahap.',vehicles:'Harga aset dan nilai residu digunakan untuk penyusutan garis lurus bulanan. Biaya mitra: nominal tetap atau persen dari tagihan layanan selesai.'})[kind]||'Perubahan disimpan ke database dan dicatat dalam riwayat audit.';$('#save').disabled=false;$('#modal').showModal();updateConditional();}
function updateConditional(){if(!editing)return;const form=$('#form'),kind=editing.kind;if(kind==='entries'){const type=form.elements.type.value||'payment';const show={toAccount:type==='transfer',booking:['payment','refund','deposit','depositReturn','depositDeduction'].includes(type),expense:type==='expensePayment',loan:type.startsWith('loan'),account:type!=='depositDeduction'};for(const [key,visible]of Object.entries(show)){const el=form.elements[key];if(el){el.parentElement.hidden=!visible;el.required=visible}}}
if(kind==='bookings'){const service=form.elements.service.value;const termBox=$('#fields .terms');if(termBox)termBox.textContent=s.settings.termsByService?.[service]||s.settings.terms;const isTravel=service==='Travel per kursi';for(const k of ['trip','seats','passengersText'])form.elements[k].parentElement.hidden=!isTravel;form.elements.trip.required=isTravel;form.elements.passengersText.required=isTravel;const trip=get('trips',form.elements.trip.value);if(isTravel&&trip){for(const key of ['vehicle','driver','start','end'])form.elements[key].value=trip[key]||'';form.elements.fee.value=trip.fare*Number(form.elements.seats.value||1)}for(const key of ['vehicle','driver','start','end'])form.elements[key].disabled=isTravel;}
}
$('#form').onchange=updateConditional;
async function collect(){const form=$('#form'),r={...editing.record};for(const d of fieldDefs){const el=form.elements[d.key];if(['display'].includes(d.type))continue;if(d.type==='permissions')r[d.key]=[...form.querySelectorAll(`input[name="${d.key}"]:checked`)].map(x=>x.value);else if(d.type==='checkbox')r[d.key]=el.checked;else if(d.type==='number')r[d.key]=Number(el.value);else if(d.type==='files'){r[d.key]=Array.isArray(r[d.key])?r[d.key]:[];for(const file of el.files){if(file.size>5*1024*1024)throw Error('Berkas '+file.name+' melebihi 5 MB.');const response=await fetch('/api/files?mode='+mode+'&scope='+d.scope+'&name='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':file.type},body:file});const data=await response.json();if(!response.ok)throw Error(data.error);r[d.key].push(data)}}else r[d.key]=el.value.trim();}if(editing.kind==='settings'){r.termsByService={};['Rental lepas kunci','Rental dengan pengemudi','Antar jemput bandara','Charter perjalanan','Travel per kursi'].forEach((service,i)=>{r.termsByService[service]=r['serviceTerms'+i];delete r['serviceTerms'+i]});r.users=r.usersText.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const [email,role]=x.split(',').map(x=>x.trim());return {email,role}});delete r.usersText;}if(editing.kind==='bookings'){r.passengers=(r.passengersText||'').split('\n').map(x=>x.trim()).filter(Boolean);delete r.passengersText;if(r.service==='Travel per kursi'){const t=get('trips',r.trip);if(!t)throw Error('Pilih jadwal travel.');for(const k of ['vehicle','driver','start','end'])r[k]=t[k];r.fee=t.fare*r.seats}else{r.trip='';r.seats=0;r.passengers=[]}if(r.vehicle){const v=get('vehicles',r.vehicle);if(v?.active===false)throw Error('Kendaraan nonaktif.');}if(r.status==='confirmed'&&!r.accepted)throw Error('Persetujuan syarat sewa wajib.');}if(editing.kind==='entries'){const type=r.type;if(!['payment','refund','deposit','depositReturn','depositDeduction'].includes(type))r.booking='';if(type!=='expensePayment')r.expense='';if(!type.startsWith('loan'))r.loan='';if(type!=='transfer')r.toAccount='';if(type==='depositDeduction')r.account='';}if(editing.kind==='expenses'&&r.booking&&!r.vehicle)r.vehicle=get('bookings',r.booking)?.vehicle||'';r.id=r.id||id();return r;}
$('#form').onsubmit=async e=>{e.preventDefault();$('#save').disabled=true;try{const r=await collect();if(editing.callback)await editing.callback(r);else await change(editing.kind,r,editing.record.id?'Ubah data':'Tambah data');$('#modal').close()}catch(e){toast(e.message)}finally{$('#save').disabled=false}};
$('#close').onclick=$('#cancel').onclick=()=>$('#modal').close();$('#detail-close').onclick=()=>$('#detail').close();
function detail(title,html){$('#detail-title').textContent=title;$('#detail-content').innerHTML=html;$('#detail').showModal()}
function bookingDetail(b){const c=get('customers',b.customer),v=get('vehicles',b.vehicle),col=s.collaterals.filter(c=>c.booking===b.id);detail(b.number,row('Pelanggan',esc(c?.name))+row('Layanan',esc(b.service))+row('Jadwal',esc(b.start.replace('T',' ')+' → '+b.end.replace('T',' ')))+row('Kendaraan',esc(v?.name||'—'))+row('Status',STATUS[b.status])+(allow('finance')?row('Tagihan / terbayar',rp(total(b))+' / '+rp(paid(s,b.id)))+row('Sisa piutang',rp(Math.max(0,total(b)-paid(s,b.id))))+row('Saldo uang jaminan',rp(deposit(s,b.id))):'')+`<div class="terms">${esc(b.termsSnapshot||s.settings.termsByService?.[b.service]||s.settings.terms)}</div><p class="note">${b.accepted?'Persetujuan penyewa dicatat.':'Belum ada persetujuan penyewa.'}${c?.licenseExpiry&&c.licenseExpiry<b.end.slice(0,10)?' PERINGATAN: SIM habis sebelum masa sewa berakhir.':''}</p><div class="actions">${allow('finance')?btn('payment','＋ DP / pembayaran',b.id)+btn('deposit','＋ Uang jaminan',b.id):''}${allow('documents')?btn('new-collateral','＋ Jaminan kendaraan',b.id):''}</div>`+col.map(x=>`<div class="panel"><h3>Jaminan ${esc(x.type+' '+x.plate)}</h3><p>${esc(x.name)} · Pemilik ${esc(x.owner)}</p>${row('Status',{pending:'Belum diserahkan',received:'Diterima',returned:'Dikembalikan'}[x.status])}${row('Kondisi diterima',esc(x.condition||'—'))}${row('Kelengkapan',esc(x.items||'—'))}${row('Diterima',esc((x.receivedAt||'—')+' / '+(x.receivedBy||'—')))}${row('Dikembalikan',esc((x.returnedAt||'—')+' / '+(x.returnedBy||'—')))}${allow('documents')?files([...(x.files||[]),...(x.returnFiles||[]),...(x.consentFiles||[])])+`<div class="actions">${edit('collaterals',x)}${btn('collateral-receipt','Tanda terima PDF',x.id)}</div>`:''}</div>`).join(''));}
function history(kind,key){const bs=s.bookings.filter(b=>b[kind==='drivers'?'driver':'vehicle']===key);const expenses=s.expenses.filter(e=>e[kind==='drivers'?'driver':'vehicle']===key);detail(name(kind,key),table(['PEMESANAN','JADWAL','STATUS','TAGIHAN'],bs.map(b=>[esc(b.number),esc(b.start.replace('T',' ')),st(b),allow('finance')?rp(total(b)):'—']))+(allow('finance')?table(['TAGIHAN JASA / BIAYA','TOTAL','SUDAH DIBAYAR'],expenses.map(e=>[esc(e.description),rp(e.amount),rp(expensePaid(s,e.id))])):''));}
async function setStatus(b){const choices={draft:['confirmed','cancelled'],confirmed:['ongoing','cancelled'],ongoing:['completed','cancelled'],completed:['cancelled'],cancelled:[]}[b.status];editing={kind:'status',record:{id:b.id},callback:async r=>{if(r.status==='confirmed'&&!r.accepted)throw Error('Penyewa harus menyetujui syarat sewa.');const patch={id:b.id,status:r.status};if(b.status==='draft'){patch.accepted=r.accepted;patch.termsSnapshot=s.settings.terms}if(r.status==='cancelled'){if(!r.cancelReason)throw Error('Isi alasan pembatalan.');patch.cancelReason=r.cancelReason}await change('bookings',patch,'Status: '+STATUS[r.status]);}};fieldDefs=[select('status','Status berikutnya',choices.map(x=>[x,STATUS[x]])),f('termsDisplay','Syarat yang disetujui','display',{value:b.termsSnapshot||s.settings.termsByService?.[b.service]||s.settings.terms,full:true}),check('accepted','Penyewa sudah menyetujui syarat sewa',b.accepted),f('cancelReason','Alasan pembatalan (wajib untuk pembatalan)','textarea',{required:false,full:true})];$('#modal-title').textContent='Status '+b.number;$('#fields').innerHTML=fieldDefs.map(d=>fieldHtml(d,{})).join('');$('#form-note').textContent='Serah terima lepas kunci memerlukan dokumen terverifikasi dan jaminan diterima. Pembatalan tidak otomatis mengembalikan pembayaran: catat refund terpisah.';$('#save').disabled=false;$('#modal').showModal()}
async function voidRecord(kind,key){const reason=prompt('Alasan pembatalan (riwayat tetap disimpan):');if(!reason?.trim())return;await change(kind,{id:key,void:true,voidReason:reason.trim()},'Batalkan transaksi');}
async function action(a,key){try{switch(a){case'new':openForm(key);break;case'new-booking':openForm('bookings');break;case'edit':{const[k,i]=key.split(':');if($('#detail').open)$('#detail').close();openForm(k,get(k,i));break}case'booking-detail':bookingDetail(get('bookings',key));break;case'status':await setStatus(get('bookings',key));break;case'invoice':if(!allow('finance'))throw Error('Izin keuangan diperlukan untuk invoice.');invoice(get('bookings',key));break;case'payment':case'deposit':$('#detail').close();openForm('entries',{}, {booking:key,type:a==='deposit'?'deposit':'payment',description:(a==='deposit'?'Jaminan ':'Pembayaran ')+name('bookings',key)});break;case'new-collateral':$('#detail').close();openForm('collaterals',{}, {booking:key});break;case'customer-detail':{const c=get('customers',key);detail(c.name,row('HP',esc(c.phone))+row('Alamat',esc(c.address||'—'))+row('Kontak darurat',esc(c.emergency||'—'))+row('SIM berlaku',esc(c.licenseExpiry||'—'))+(allow('documents')?files(c.files)+`<div class="actions">${(c.files||[]).map(f=>btn('delete-file','Hapus berkas: '+esc(f.name),f.id,'danger')).join('')}</div>`:'<p>Dokumen privat memerlukan izin.</p>'));break}case'driver-history':history('drivers',key);break;case'vehicle-history':history('vehicles',key);break;case'finance-tab':section=key;render();break;case'pay-expense':{const e=get('expenses',key);openForm('entries',{}, {type:'expensePayment',expense:key,amount:Math.max(0,e.amount-expensePaid(s,key)),description:'Bayar '+e.description});break}case'loan-payment':openForm('entries',{}, {type:'loanPrincipal',loan:key,description:'Cicilan '+name('loans',key)});break;case'void-entry':await voidRecord('entries',key);break;case'void-expense':await voidRecord('expenses',key);break;case'settle-partner':{const b=get('bookings',key),v=get('vehicles',b.vehicle);const amount=v.partnerScheme==='percent'?Math.round(total(b)*v.partnerFee/100):v.partnerFee;await change('expenses',{id:id(),date:b.end.slice(0,10),due:today(),category:'Sewa kendaraan mitra',description:'Mitra '+v.partnerName+' · '+b.number,amount,vehicle:v.id,booking:b.id,payee:v.partnerName,files:[],partnerSettlement:b.id},'Buat tagihan mitra');break}case'reserve-seat':openForm('bookings',{}, {service:'Travel per kursi',trip:key});break;case'passengers':{const list=s.bookings.filter(b=>b.trip===key&&!['draft','cancelled'].includes(b.status));detail('Daftar penumpang',table(['PEMESANAN','PELANGGAN','PENUMPANG'],list.map(b=>[esc(b.number),esc(name('customers',b.customer)),b.passengers.map(esc).join('<br>')])));break}case'collateral-receipt':await collateralPDF(get('collaterals',key));break;case'settings-edit':openForm('settings',s.settings);break;case'backup':{download('kelola-cadangan-'+today()+'.json',JSON.stringify(await api('/api/backup'),null,2),'application/json');break}case'restore':$('#restore-file').click();break;case'migrate':{let old=localStorage.getItem('dp-trans-finance-v1');if(!old){toast('Tidak ada data lokal versi lama di browser ini. Gunakan Pulihkan JSON untuk mengimpor cadangan lama.');return}if(confirm('Impor catatan kas lama? Pendapatan lama dianggap layanan selesai. Catatan yang sudah diimpor jangan diimpor ulang.')){adopt(await api('/api/restore',{revision:rev,data:JSON.parse(old)}));toast('Data lama berhasil diimpor.')}break}case'purge-files':if(confirm('Hapus permanen semua dokumen yang masa simpannya telah berakhir?')){const r=await api('/api/files/delete',{expired:true});toast(r.deleted+' dokumen dihapus.');await load()}break;case'delete-file':if(confirm('Hapus berkas ini secara permanen? Pastikan salinan arsip sudah disimpan jika diperlukan.')){await api('/api/files/delete',{id:key});$('#detail').close();await load();toast('Berkas dihapus permanen.')}break;case'pdf-report':await reportPDF();break;case'excel':exportExcel();break;case'pdf-invoice':await invoicePDF(get('bookings',key));break;case'whatsapp':shareInvoice(get('bookings',key));break;}}
catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b)action(b.dataset.act,b.dataset.id)});$('#nav').onclick=e=>{const b=e.target.closest('[data-nav]');if(b){page=b.dataset.nav;$('#search').value='';render()}};$('#quick-booking').onclick=()=>openForm('bookings');$('#quick-income').onclick=()=>openForm('entries',{}, {type:'payment'});$('#quick-expense').onclick=()=>openForm('expenses');$('#reload').onclick=load;$('#search').oninput=render;
['#period','#from','#to'].forEach(x=>$(x).onchange=()=>{if(x!=='#period')$('#period').value='custom';const[a,b]=period();$('#from').value=a;$('#to').value=b;if(a>b)toast('Tanggal awal harus sebelum tanggal akhir.');render()});[$('#from').value,$('#to').value]=period();
$('#demo').onclick=async()=>{try{mode='demo';adopt(await api('/api/demo',{}));toast('Anda berada di mode contoh. Data usaha asli tetap terpisah.')}catch(e){mode='live';toast(e.message)}};$('#exit-demo').onclick=()=>{mode='live';load()};document.addEventListener('change',async e=>{if(e.target.id!=='restore-file')return;const file=e.target.files[0];try{if(!file||file.size>20000000)throw Error('Pilih JSON maksimal 20 MB.');const data=JSON.parse(await file.text());if(confirm('Pulihkan cadangan ke mode '+mode+'? Database saat ini diganti. Unduh cadangan sebelum melanjutkan.')){adopt(await api('/api/restore',{revision:rev,data}));toast('Cadangan dipulihkan.')}}catch(e){toast(e.message)}finally{e.target.value=''}});
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true}};if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.addEventListener('offline',()=>toast('Koneksi terputus. Data baru memerlukan internet; formulir tetap terbuka.'));
function invoice(b){const c=get('customers',b.customer);detail('Invoice '+b.number,`<div class="invoice"><div class="invoice-head"><div><img class="logo" src="/logo.png" alt="Logo usaha"><h2>${esc(s.settings.name)}</h2></div><div><h2>INVOICE</h2><b>INV-${esc(b.number)}</b><p>${esc(STATUS[b.status])}</p></div></div>${row('Kepada',esc(c?.name)+' · '+esc(c?.phone))}${row('Layanan',esc(b.service))}${row('Jadwal',esc(b.start.replace('T',' ')+' → '+b.end.replace('T',' ')))}${row('Armada / pengemudi',esc(name('vehicles',b.vehicle)+' / '+name('drivers',b.driver)))}${row('Rute / tujuan',esc(b.pickup||'—')+' → '+esc(b.destination||name('routes',get('trips',b.trip)?.route)))}${row('Tarif',rp(b.fee))}${row('Diskon',rp(b.discount))}${row('Biaya tambahan',rp(b.extra))}${row('Total tagihan',rp(total(b)),true)}${row('Pembayaran bersih',rp(paid(s,b.id)))}${row('Sisa tagihan',rp(b.status==='cancelled'?0:Math.max(0,total(b)-paid(s,b.id))),true)}${row('Jaminan uang (terpisah)',rp(deposit(s,b.id)))}<div class="bank">Rekening tujuan\n${esc(s.settings.bankInfo||'Hubungi petugas untuk rekening pembayaran.')}</div><p class="note">${b.status==='cancelled'?'Pemesanan dibatalkan; pembayaran yang belum direfund menjadi kewajiban pengembalian.':'Simpan invoice ini sebagai referensi pemesanan. Uang jaminan tidak termasuk pendapatan layanan.'}</p></div><div class="actions no-print">${btn('pdf-invoice','↓ Unduh PDF',b.id,'primary')}${btn('whatsapp','Bagikan ke WhatsApp',b.id)}</div>`)}
function invoiceLines(b){return ['INVOICE INV-'+b.number,s.settings.name,'Pelanggan: '+name('customers',b.customer),'Layanan: '+b.service,'Status: '+STATUS[b.status],'Jadwal: '+b.start.replace('T',' ')+' s.d. '+b.end.replace('T',' '),'Kendaraan: '+name('vehicles',b.vehicle),'Pengemudi: '+name('drivers',b.driver),'Lokasi jemput: '+(b.pickup||'-'),'Tujuan: '+(b.destination||name('routes',get('trips',b.trip)?.route)),'Tarif: '+rp(b.fee),'Diskon: '+rp(b.discount),'Biaya tambahan: '+rp(b.extra),'TOTAL TAGIHAN: '+rp(total(b)),'Pembayaran bersih: '+rp(paid(s,b.id)),'SISA TAGIHAN: '+rp(b.status==='cancelled'?0:Math.max(0,total(b)-paid(s,b.id))),'Saldo uang jaminan (terpisah): '+rp(deposit(s,b.id)),'','Pembayaran pelanggan:',...s.entries.filter(e=>!e.void&&e.booking===b.id&&['payment','refund','depositDeduction'].includes(e.type)).map(e=>`${e.date} | ${TYPES[e.type]} | ${rp(e.amount)} | ${e.method||'-'}`),'','Rekening tujuan:',s.settings.bankInfo||'Hubungi petugas untuk rekening pembayaran.','',b.status==='cancelled'?'DIBATALKAN. Pembayaran yang belum direfund wajib diselesaikan.':'Terima kasih atas kepercayaan Anda.']}
function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function ascii(t){return String(t).normalize('NFKD').replace(/[^\x20-\x7e\n]/g,' ').replace(/\s+/g,' ').trim()}
function wrap(text,width=86){const words=ascii(text).split(' '),lines=[];let line='';for(const word of words){if((line+' '+word).length>width&&line){lines.push(line);line=word}else line+=(line?' ':'')+word}lines.push(line);return lines}
async function pdfBlob(title,lines){const img=new Image();img.src='/logo.png';await img.decode();const canvas=document.createElement('canvas');canvas.width=600;canvas.height=180;const c=canvas.getContext('2d');c.fillStyle='#102b49';c.fillRect(0,0,600,180);const scale=580/img.width;c.drawImage(img,10,(180-img.height*scale)/2,img.width*scale,img.height*scale);const jpg=atob(canvas.toDataURL('image/jpeg',.88).split(',')[1]);const all=lines.flatMap(l=>wrap(l)),pages=[];for(let i=0;i<all.length;i+=43)pages.push(all.slice(i,i+43));if(!pages.length)pages.push([]);const objects=[],add=x=>{objects.push(x);return objects.length},font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'),image=add(`<< /Type /XObject /Subtype /Image /Width 600 /Height 180 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n${jpg}\nendstream`),catalog=add(''),root=add(''),pageIds=[];const safe=t=>ascii(t).replace(/([\\()])/g,'\\$1');for(let pi=0;pi<pages.length;pi++){let stream='q 160 0 0 48 40 752 cm /Logo Do Q\n';stream+=`BT /F1 15 Tf 40 724 Td (${safe(title)}) Tj ET\nBT /F1 9 Tf 40 700 Td 14 TL\n`;stream+=pages[pi].map((l,i)=>`${i?'T* ':''}(${safe(l)}) Tj`).join('\n');stream+=`\nET\nBT /F1 8 Tf 40 35 Td (Kelola Rental & Travel | ${today()} | Halaman ${pi+1}/${pages.length}) Tj ET`;const content=add(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);pageIds.push(add(`<< /Type /Page /Parent ${root} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${font} 0 R >> /XObject << /Logo ${image} 0 R >> >> /Contents ${content} 0 R >>`))}objects[catalog-1]=`<< /Type /Catalog /Pages ${root} 0 R >>`;objects[root-1]=`<< /Type /Pages /Count ${pageIds.length} /Kids [${pageIds.map(i=>i+' 0 R').join(' ')}] >>`;let out='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(out.length);out+=`${i+1} 0 obj\n${o}\nendobj\n`});const xref=out.length;out+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length+1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([Uint8Array.from(out,x=>x.charCodeAt(0))],{type:'application/pdf'})}
async function invoicePDF(b){download('Invoice-'+b.number+'.pdf',await pdfBlob('Invoice '+b.number,invoiceLines(b)),'application/pdf');toast('Invoice PDF diunduh.')}
async function collateralPDF(x){const b=get('bookings',x.booking);const lines=['TANDA TERIMA JAMINAN KENDARAAN',s.settings.name,'Pemesanan: '+b.number,'Penyewa: '+name('customers',b.customer),'Jaminan: '+x.type+' '+x.name+' / '+x.plate,'Warna: '+x.color,'Pemilik: '+x.owner,'Status: '+({pending:'Belum diserahkan',received:'Diterima',returned:'Dikembalikan'}[x.status]),'Diterima pada: '+(x.receivedAt||'-'),'Petugas: '+(x.receivedBy||'-'),'Kondisi diterima: '+(x.condition||'-'),'Kelengkapan: '+(x.items||'-'),'Persetujuan penyewa: '+(x.renterConsent?'Dicatat oleh petugas':'Belum dicatat'),'Dikembalikan pada: '+(x.returnedAt||'-'),'Petugas pengembalian: '+(x.returnedBy||'-'),'Kondisi kembali: '+(x.returnCondition||'-'),'Kelengkapan kembali: '+(x.returnItems||'-'),'Penyelesaian: '+(x.settlement||'-'),'','Jaminan kendaraan bukan aset atau pemasukan usaha.','Tanda tangan penyewa: ____________________','Tanda tangan petugas: ____________________'];download('Tanda-terima-'+b.number+'.pdf',await pdfBlob('Tanda terima jaminan',lines),'application/pdf')}
async function shareInvoice(b){const blob=await pdfBlob('Invoice '+b.number,invoiceLines(b)),file=new File([blob],'Invoice-'+b.number+'.pdf',{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Invoice '+b.number,text:'Invoice '+s.settings.name+'. Pilih WhatsApp untuk mengirim berkas PDF.'});return}catch(e){if(e.name==='AbortError')return}}const c=get('customers',b.customer),phone=(c?.phone||'').replace(/\D/g,'').replace(/^0/,'62'),text=`Invoice ${b.number}\n${s.settings.name}\n${b.service}\nTagihan ${rp(total(b))}\nTerbayar ${rp(paid(s,b.id))}\nSisa ${rp(Math.max(0,total(b)-paid(s,b.id)))}\n${s.settings.bankInfo}`;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener');toast('Ringkasan dibuka di WhatsApp. Unduh PDF lalu lampirkan jika berbagi berkas tidak tersedia.')}
function reportLines(){const[a,b]=period(),r=report(s,a,b);return [s.settings.name,`Periode ${a} s.d. ${b}`,'LABA RUGI (AKRUAL)','Pendapatan layanan selesai: '+rp(r.revenue),'Beban operasional: '+rp(r.expense),'Bunga cicilan: '+rp(r.interest),'Penyusutan: '+rp(r.depreciation),'LABA / RUGI: '+rp(r.profit),'','ARUS KAS','Uang masuk: '+rp(r.cashIn),'Uang keluar: '+rp(r.cashOut),'Perubahan kas: '+rp(r.netCash),...r.balances.map(a=>a.name+': '+rp(a.balance)),'Piutang: '+rp(r.receivables),'Utang pengeluaran: '+rp(r.expenseDebt),'Utang pokok pinjaman: '+rp(r.loans),'Uang muka belum diakui: '+rp(r.deferred),'Jaminan uang: '+rp(r.deposits),'Refund tertunda: '+rp(r.refunds),'',...$$('#content .panel').flatMap(p=>[p.querySelector('h3')?.textContent||'',...[...p.querySelectorAll('tr')].map(tr=>[...tr.children].map(td=>td.innerText.replace(/\n/g,' ')).join(' | '))]),'','Penyusutan garis lurus bulanan, termasuk bulan perolehan/akhir periode. Laba pemesanan/rute hanya memperhitungkan biaya langsung. Pajak belum dihitung otomatis.']}
async function reportPDF(){download('Laporan-'+today()+'.pdf',await pdfBlob('Laporan usaha',reportLines()),'application/pdf');toast('Laporan PDF diunduh.')}
function xml(s){return String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'')}
function zip(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;const u16=(v,n,o)=>v.setUint16(o,n,true),u32=(v,n,o)=>v.setUint32(o,n,true);const crc=data=>{let n=0xffffffff;for(const b of data){n^=b;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xedb88320:0)}return (n^0xffffffff)>>>0};for(const[name,text]of Object.entries(files)){const key=enc.encode(name),data=enc.encode(text),sum=crc(data),head=new Uint8Array(30+key.length),v=new DataView(head.buffer);u32(v,0x04034b50,0);u16(v,20,4);u32(v,sum,14);u32(v,data.length,18);u32(v,data.length,22);u16(v,key.length,26);head.set(key,30);chunks.push(head,data);const c=new Uint8Array(46+key.length),cv=new DataView(c.buffer);u32(cv,0x02014b50,0);u16(cv,20,4);u16(cv,20,6);u32(cv,sum,16);u32(cv,data.length,20);u32(cv,data.length,24);u16(cv,key.length,28);u32(cv,offset,42);c.set(key,46);central.push(c);offset+=head.length+data.length}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0x06054b50,0);u16(ev,central.length,8);u16(ev,central.length,10);u32(ev,size,12);u32(ev,offset,16);return new Blob([...chunks,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function exportExcel(){const lines=reportLines().map(l=>l.split(' | '));const columns=i=>{let a='';for(i++;i;i=Math.floor((i-1)/26))a=String.fromCharCode(65+(i-1)%26)+a;return a};const sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+lines.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>`<c r="${columns(j)}${i+1}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')}</row>`).join('')+'</sheetData></worksheet>';const blob=zip({'[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Laporan Usaha" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':sheet});download('Laporan-'+today()+'.xlsx',blob,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Laporan Excel diunduh.')}
